import{_ as p,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const d=JSON.parse('{"title":"学易笔谈述旨","description":"杭氏易学 - 学易笔谈述旨","frontmatter":{"title":"学易笔谈述旨","description":"杭氏易学 - 学易笔谈述旨"},"headers":[],"relativePath":"zh/classics/hangshi/021.md","filePath":"zh/classics/hangshi/021.md"}'),r={name:"zh/classics/hangshi/021.md"};function i(n,a,c,_,o,h){return t(),e("div",null,[...a[0]||(a[0]=[s('<h1 id="学易笔谈述旨" tabindex="-1">学易笔谈述旨 <a class="header-anchor" href="#学易笔谈述旨" aria-label="Permalink to “学易笔谈述旨”">​</a></h1><p>《易》道至大，《易》理至遂；辛斋之愚，何敢妄谈？顾念吾师忍死狴犴，克期以待，密传心法，冀绵绝学，又曷敢自弃？丙辰出狱，爰搜集古今说《易》之书，惟日孳孳，寝馈舟车，未尝或辍。丁巳以后，国会蒙尘。播越岭峤，议席多暇，两院同人，合组研几学社于广州之迥龙社。谬推都讲，计日分程，商兑讲习。虽兵戈扰攘，而课约罔闲。讲义纂辑，得书若干，名曰《易楔》。而晨昏余晷，切磋问难，随时笔录者，又积稿盈尺。同人艰于传写，乃谋刊印。厘为四卷，名曰《笔谈》，盖纪实焉。己未庚申，由粤而沪。同志之友，闻声毕集。风雨一庐，不废讨论。以续前稿，又得四卷，另为《二集》。借阅传钞，恐多遗失。适前印之书，久已告罄。同人请合两《集》与《易楔》、《易数偶得》、《读易杂记》诸稿，均以聚珍板印行。始于壬戌八月，至十月抄，《笔谈》八卷工竣。爰纪颠末，并述旨如左。</p><p>一、承学之士，不废笔札，谈论所及，择要缀录，聊以备忘。除《初集》第一卷，于临印时略有增减，以明源流外，余悉随时编订，并无先后次序。</p><p>二、讲《易》与诂经不同。诂经当有家法，有体例，义不容杂。而讲《易》则以阐明卦爻象数之原理原则，但以经文为之证明。故凡与象数有涉，足与《易》道相发明者，博采旁搜，不限时地，更无所谓门户派别也。</p><p>三、《易》本法象于天地。乾易坤简，易知易能，虽见仁见智，各随学识之深浅而异，要无不可知之理。自象义不明，学者无所适从，几视《易》为绝学，而不敢问津。致《易》简之理，日即湮晦。本编有鉴于斯，立说皆取浅显明 白，务期尽人能解，不敢以艰深文浅陋也。</p><p>四、孔子赞《易》，身逢乱世，行危言逊。有因时忌不能显言者，不得不以微言大义，隐寓于象数之中，与春秋同一例也。后人不察，悉以文字求之，孔子忧天悯人之苦心湮没尽矣。历代学者，如邵康节，如刘青田、黄姚江，均抱此隐痛而未敢昌言者也。鼎革以后，世虽乱而言可无讳。发历圣之心传，弥前贤之遗憾，维世道而存绝学，不可谓非千载一时之良机。剥极必复，时乎不再，幸我同人勿自暴弃以负天心也。</p><p>五、卦因数衍，数缘象起，象由心生。《易》准天地，广大悉备。虽人事递演，世变日繁，要不能出乎此象数之外。故洲殊种别，文字语言，万有不齐，维数足以齐之。宗教俗尚，各有不同，惟数足以同之。两千年来，数学失传。宋后言《易》者，往往以邵子先天数为《易》数。数理繁啧，固非短扎所能尽。然于旧说之显然挑牴牾者，不能不援据象数以为商榷，非敢故翻成案也。</p><p>六、占筮固《易》之一端，而圣人修《易》以明道，实非尽为占筮。孔子赞《易》，绍述文周，以人合天，兢兢寡过，岂导人于趋吉避凶哉！朱子以占筮为《易》之本义，未免偏见。而《大衍》揲蓍之法，自唐以后，于挂一再扐两端，立说互歧。往诸数理，并多遗憾。未敢盲从，以误后人。</p><p>七、至诚之道，虽可前知，惟道本一贯，学无躐等。必正心修身，能尽人之道以合天，斯天人契合，感而遂通，百世可知。初无二理。若一知半解，妄谈祸福，自欺欺人，实学《易》之大戒。兢兢自箴者，窃愿以此勉人。</p><p>八、尽性至命，乃易学之极功。孔子之圣，犹韦编三绝，但云寡过，罕言性命。后生末学，更宜践履笃实，下学上达。同学讲习，窃本斯旨。《初集》刊布，朋自远来，往往以只言象数，不谈身心性命相责。但愚尚以象数之未能尽明为憾。果象数通解，则身心性命之理，胥在其中，更无待言说为也。</p><p>九、形而下者谓之器，形而上者谓之道。凡有形可指者皆器。道本于心，未可以言尽焉。故八卦因重，羲农法天以垂象；两编《十翼》，周孔立言以明道。然未可遽执卦象经传以为道也。譬诸升高必以梯，而梯非高。求饱必以饭，而饭非饱。宋后讲《易》，开口言性理，言道统，是犹指梯而称高，看饭而说饱也。今之谈道者，无宋人之学，而立说更高出宋人。自误误人，更不待言。愿学者共明斯旨，各求实学，返诸身心。勿好高鹜远，循前车之覆辙焉。</p><p>十、洁净精微之学，非潜修静养，未能深造。劳人草草，敢言心得？惟汇积年涉猎所得，聊供同学参考之便。深望海内鸿硕，时加匡正。幸得学与年进，尚拟续，以供采择。</p><p>十一、世道陵夷，圣学中绝。人欲横流，罔知纪极。谨愿之士，苦身心之无所寄托，蒿目时艰，恒怀消极。或附托西教，或皈向佛门。而仙灵神鬼，导引修养，及飞鸾显化之坛宇，遂遍于域中。影附风从，是丹非素。不知我国固有之学，贯澈天人，足以安身立命。保世滋大，概群藉而罗万有者，悉在此一画开天，人文肇始之《易经》。存人道，挽世运，千钧一发，绝续在兹。弘道救世，责无旁贷。惟我同人，自奋勉焉。</p>',13)])])}const m=p(r,[["render",i]]);export{d as __pageData,m as default};
